CREATE MATERIALIZED VIEW `mv_ads_franchisees_purchase_sales_df` (`biz_date` COMMENT "日期", `store_code` COMMENT "门店代码", `store_name` COMMENT "门店名称", `ownership_type` COMMENT "门店所有权类型", `item_code` COMMENT "商品代码", `item_name` COMMENT "商品名称", `item_barcode` COMMENT "商品条码", `item_spec` COMMENT "商品规格", `store_wrh_num` COMMENT "期初数量", `store_wrh_amt` COMMENT "期初金额", `receive_quantity` COMMENT "收货数量", `receive_amt` COMMENT "收货金额", `actual_receive_num` COMMENT "直送数量", `item_reduction_qty` COMMENT "销售退货数量", `mt_item_reduction_qty` COMMENT "美团销售退货数量", `item_add_qty` COMMENT "销售数量", `mt_item_add_qty` COMMENT "美团销售数量", `item_add_amt` COMMENT "销售金额", `mt_item_add_amt` COMMENT "美团销售金额", `item_reduction_amt` COMMENT "销售退货金额", `mt_item_reduction_amt` COMMENT "美团销售退货金额", `package_goods_amount` COMMENT "直送金额", `original_stock` COMMENT "原始库存", `adjust_add_count` COMMENT "库存调整（增）数量", `adjust_reduction_count` COMMENT "库存调整（减）数量", `adjust_add_count_source_null` COMMENT "库存调整（增）数量来源单号空", `adjust_reduction_count_source_null` COMMENT "库存调整（减）数量来源单号空", `inventory_price` COMMENT "库存价", `reject_add_apply_number` COMMENT "收货差异多收驳回数量", `reject_reduction_apply_number` COMMENT "收货差异少收驳回数量", `difference_add_apply_number` COMMENT "收货差异多收数量", `difference_reduction_apply_number` COMMENT "差异少收数量", `reject_add_apply_amount` COMMENT "收货差异多收驳回金额", `reject_reduction_apply_amount` COMMENT "收货差异少收驳回金额", `difference_add_apply_amount` COMMENT "收货差异多收金额", `difference_reduction_apply_amount` COMMENT "差异少收金额", `reject_return_number` COMMENT "退货驳回数量", `return_number` COMMENT "退货数量", `reject_return_amount` COMMENT "退货驳回金额", `return_amount` COMMENT "退货金额", `direct_return_quantity` COMMENT "直送退货数量", `direct_return_amount` COMMENT "直送退货金额", `special_raw_quantity` COMMENT "特殊转移原材料数量", `special_item_quantity` COMMENT "特殊转移成品数量", `special_raw_amt` COMMENT "特殊转移原材料金额", `special_item_amt` COMMENT "特殊转移成品金额", `final_quantity` COMMENT "期末数量", `final_amt` COMMENT "期末金额", `transit_num` COMMENT "在途数量", `transit_amount` COMMENT "在途金额", `bake_loss_count` COMMENT "烘焙报损数量", `bake_loss_amt` COMMENT "烘焙报损金额", `etl_time` COMMENT "ETL_TIME")
COMMENT "加盟商进销存日报"
PARTITION BY (date_trunc('day', `biz_date`))
DISTRIBUTED BY HASH(`biz_date`, `store_code`, `item_code`) BUCKETS 12
REFRESH MANUAL
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"datacache.enable" = "true",
"enable_async_write_back" = "false",
"storage_volume" = "def_volume",
"warehouse" = "default_warehouse"
)
AS WITH `barcode` (`barcode`, `item_code`) AS (SELECT group_concat(`dwd`.`a`.`barcode` SEPARATOR ',') AS `barcode`, `dwd`.`b`.`item_code`
FROM `dwd`.`dim_item_barcode_da` AS `a` INNER JOIN `dwd`.`dim_item` AS `b` ON `dwd`.`a`.`item_id` = `dwd`.`b`.`item_id`
WHERE (`dwd`.`a`.`qpc_str` = '1*1') AND (`dwd`.`a`.`barcode` != `dwd`.`b`.`item_code`)
GROUP BY `dwd`.`b`.`item_code`) SELECT `dws`.`a`.`biz_date`, `dws`.`a`.`store_code`, `dwd`.`b`.`store_name`, `dws`.`a`.`ownership_type`, `ads`.`c`.`item_code`, `ads`.`c`.`item_name`, `d`.`barcode`, `ads`.`c`.`item_unit`, `dws`.`a`.`store_wrh_num`, `dws`.`a`.`store_wrh_amt`, `dws`.`a`.`receive_quantity`, `dws`.`a`.`receive_amt`, `dws`.`a`.`actual_receive_num`, `dws`.`a`.`item_reduction_qty`, `dws`.`a`.`mt_item_reduction_qty`, `dws`.`a`.`item_add_qty`, `dws`.`a`.`mt_item_add_qty`, `dws`.`a`.`item_add_amt`, `dws`.`a`.`mt_item_add_amt`, `dws`.`a`.`item_reduction_amt`, `dws`.`a`.`mt_item_reduction_amt`, `dws`.`a`.`package_goods_amount`, `dws`.`a`.`original_stock`, `dws`.`a`.`adjust_add_count`, `dws`.`a`.`adjust_reduction_count`, `dws`.`a`.`adjust_add_count_source_null`, `dws`.`a`.`adjust_reduction_count_source_null`, `dws`.`a`.`inventory_price`, `dws`.`a`.`reject_add_apply_number`, `dws`.`a`.`reject_reduction_apply_number`, `dws`.`a`.`difference_add_apply_number`, `dws`.`a`.`difference_reduction_apply_number`, `dws`.`a`.`reject_add_apply_amount`, `dws`.`a`.`reject_reduction_apply_amount`, `dws`.`a`.`difference_add_apply_amount`, `dws`.`a`.`difference_reduction_apply_amount`, `dws`.`a`.`reject_return_number`, `dws`.`a`.`return_number`, `dws`.`a`.`reject_return_amount`, `dws`.`a`.`return_amount`, `dws`.`a`.`direct_return_quantity`, `dws`.`a`.`direct_return_amount`, `dws`.`a`.`special_raw_quantity`, `dws`.`a`.`special_item_quantity`, `dws`.`a`.`special_raw_amt`, `dws`.`a`.`special_item_amt`, `dws`.`a`.`final_quantity`, `dws`.`a`.`final_amt`, `dws`.`a`.`transit_num`, `dws`.`a`.`transit_amount`, `dws`.`a`.`bake_loss_count`, `dws`.`a`.`bake_loss_amt`, `dws`.`a`.`etl_time`
FROM `dws`.`dws_store_franchisees_purchase_sales_begin_df` AS `a` LEFT OUTER JOIN `dwd`.`dim_store_ra` AS `b` ON `dws`.`a`.`store_code` = `dwd`.`b`.`store_code` LEFT OUTER JOIN `ads`.`v_ads_dim_item_master_file` AS `c` ON `dws`.`a`.`item_code` = `ads`.`c`.`item_code` LEFT OUTER JOIN `barcode` AS d ON `dws`.`a`.`item_code` = `d`.`item_code`;
